data=[]
for e in soup.select('input,select,textarea'):
 n=e.get('name')
 if not n: continue
 if e.name=='select':
  vals=[o.get('value','') for o in e.select('option[selected]')]
  for v in vals: data.append((n,v))
 elif e.name=='textarea':
  if e.text.strip(): data.append((n,e.text.strip()))
 elif e.get('type') in ('checkbox','radio'):
  if e.has_attr('checked'): data.append((n,e.get('value','on')))
 else: data.append((n,e.get('value','')))
