data=[(k,v) for k,v in data if k not in replace]
for k,v in replace.items():
 if k=='F_D76.V1':
  for y in range(2016,2021): data.append((k,str(y)))
 elif k=='V_D76.V5':
  for a in ['65-74','75-84','85+']: data.append((k,a))
