// function which is added to radio buttons by the wonder:rf-var-radio function.
function groupByActions(select) {
	var index = select.selectedIndex;
	var code = select.options[index].value;

	if (codeEquals(code, dcode, 'V11,V19')) {
		toggleRadio('O_urban', code);
		toggleDisplay(code, dcode + '.V19,' + dcode + '.V11');
	}

	if (codeEquals(code, dcode, 'V5,V51,V52,V6')) {
		toggleRadio('O_age', code);
		toggleDisplay(code, dcode + '.V5,' + dcode+'.V51,' + dcode + '.V52,' + dcode + '.V6');
	}

	if (codeEquals(code, dcode, 'V42,V43,V44')) {
		toggleRadio('O_race', code);
		toggleDisplay(code, dcode + '.V42,' + dcode+'.V43,' + dcode + '.V44');
	}

}

